export const CORE_SKILL_IDS=Object.freeze(['fire','lightning','earth','water','five_elements']);
const ALL_FUSION_SKILLS=Object.freeze({...FUSION_SKILLS,...TANG_FUSION_SKILLS});
const BASE_IDS=Object.freeze({'Hỏa Cầu Thuật':'fire','Lôi Bạo':'lightning','Thổ Thuẫn':'earth','Thủy Kiếm':'water','Ngũ Hành Diệt Sát Trận':'five_elements'});
export const getFusionBaseId=base=>BASE_IDS[base];
export function getFusionOptions(incoming,slots,character='diep_tu',coreSlots=CORE_SKILL_IDS){
 if(character!=='diep_tu')return [];
 const matches=[];
 for(const [id,s] of Object.entries(ALL_FUSION_SKILLS)){
  if(slots.includes(id)||coreSlots.includes(id))continue;
  if(s.incoming===incoming){
   const ok=s.requires?slots.includes(s.requires):coreSlots.includes(BASE_IDS[s.base]);
   if(ok)matches.push({id,...s});
  }else if(s.symmetric&&s.requires===incoming&&slots.includes(s.incoming)){
   matches.push({
    id,
    ...s,
    requires:s.incoming,
    incoming:s.requires,
    base:SKILL_LABELS[s.incoming]||s.incomingName,
    incomingName:SKILL_LABELS[s.requires]||s.base,
   });
  }
 }
 return matches;
}
